<?= $this->include('layouts/header') ?><div class="page-head"><div><div class="page-kicker">System</div><h1 class="page-title">Settings</h1><p class="page-subtitle">Basic application identity and time configuration.</p></div></div><div class="grid grid-2"><div class="card form-card"><form method="post" action="<?=site_url('settings/save')?>" enctype="multipart/form-data"><?=csrf_field()?><?php $map=array_column($settings,'setting_value','setting_key'); ?><div class="field"><label>Application name</label><input name="app_name" value="<?=esc(old('app_name',$map['app_name']??'Inventory Manager'))?>"><div class="hint">Shown in the application shell and login page.</div></div><div class="section-head" style="margin-top:22px"><div><h2 class="section-title">Company details for challans</h2><div class="section-meta">These details appear on both Original and Customer Copy.</div></div></div><div class="form-grid two"><div class="field"><label>Company name</label><input name="company_name" value="<?=esc(old('company_name',$map['company_name']??($map['app_name']??'Inventory Manager')))?>"></div><div class="field"><label>Tax / GST number</label><input name="company_tax" value="<?=esc(old('company_tax',$map['company_tax']??''))?>"></div><div class="field"><label>Phone</label><input name="company_phone" value="<?=esc(old('company_phone',$map['company_phone']??''))?>"></div><div class="field"><label>Email</label><input name="company_email" value="<?=esc(old('company_email',$map['company_email']??''))?>"></div></div><div class="field" style="margin-top:15px"><label>Address</label><textarea name="company_address" rows="3"><?=esc(old('company_address',$map['company_address']??''))?></textarea></div><div class="field" style="margin-top:15px"><label>Company logo</label><input type="file" name="company_logo_upload" accept="image/png,image/jpeg,image/webp"><div class="hint">Upload PNG, JPG/JPEG or WEBP. The same logo is used in the sidebar and both challan copies.</div><?php if(!empty($map['company_logo'])): ?><div style="margin-top:10px;display:flex;align-items:center;gap:12px"><img src="<?=preg_match('~^https?://~i',(string)$map['company_logo'])?esc($map['company_logo']):esc(base_url(ltrim((string)$map['company_logo'],'/')))?>" alt="Current company logo" style="width:72px;height:48px;object-fit:contain;border:1px solid var(--line);border-radius:10px;background:#fff;padding:5px"><span class="hint">Current logo</span></div><?php endif; ?><input type="hidden" name="company_logo" value="<?=esc(old('company_logo',$map['company_logo']??''))?>"></div><div class="field" style="margin-top:15px"><label>WhatsAppJS alerts</label><select name="whatsappjs_enabled"><option value="0" <?=($map['whatsappjs_enabled']??'0')==='0'?'selected':''?>>Disabled for now</option><option value="1" <?=($map['whatsappjs_enabled']??'0')==='1'?'selected':''?>>Enabled (integration pending)</option></select><div class="hint">The alert switch is reserved for the future WhatsAppJS integration. No messages are sent by the current version.</div></div><div class="field" style="margin-top:15px"><label>Timezone</label><input name="timezone" value="<?=esc(old('timezone',$map['timezone']??'Asia/Kolkata'))?>"><div class="hint">Use a PHP timezone such as Asia/Kolkata or UTC.</div></div><div class="form-actions"><button class="btn primary" type="submit">Save settings</button></div></form></div><div class="card"><div class="section-head"><div><h2 class="section-title">System notes</h2><div class="section-meta">Guardrails built into the application</div></div></div><div class="card-body"><div class="pill-row" style="margin-bottom:14px"><span class="pill">CSRF protected</span><span class="pill">Ledger-based stock</span><span class="pill">No destructive transaction deletes</span><span class="pill">Per-user permissions</span></div><div class="muted" style="font-size:12px">Stock is recalculated from opening balance plus confirmed IN minus confirmed OUT. Voids remove the movement from the calculation 